    const maxE = Math.min(n * (n - 1) / 2, big ? 100000 : 9);
    const m = big ? 100000 : r.int(0, maxE);
    const seen = new Set(), cables = [];
    while (cables.length < m) {
      const a = r.int(0, n - 1), b = r.int(0, n - 1);
      if (a === b) continue;
      const key = Math.min(a, b) * n + Math.max(a, b);
      if (seen.has(key)) continue;
      seen.add(key);
      cables.push([a, b]);
    }
    return [n, cables];
  }

