function movesToConnect(n: number, cables: number[][]): number {
  if (cables.length < n - 1) return -1;
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of cables) { adj[a].push(b); adj[b].push(a); }
  const seen = new Uint8Array(n);
  let groups = 0;
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    groups++;
    seen[s] = 1;
    const stack = [s];
    while (stack.length) {
      const u = stack.pop()!;
      for (const v of adj[u]) if (!seen[v]) { seen[v] = 1; stack.push(v); }
    }
  }
  return groups - 1;
}

