class Solution:
    def movesToConnect(self, n: int, cables: List[List[int]]) -> int:
        if len(cables) < n - 1:
            return -1
        adj = [[] for _ in range(n)]
        for a, b in cables:
            adj[a].append(b)
            adj[b].append(a)
        seen = [False] * n
        groups = 0
        for s in range(n):
            if seen[s]:
                continue
            groups += 1
            seen[s] = True
            stack = [s]
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not seen[v]:
                        seen[v] = True
                        stack.append(v)
        return groups - 1

